from qb import q, write

VT = ["python-developer", "backend-developer", "full-stack-developer", "frontend-developer", "mobile-app-developer"]
ITEMS = [
    q("python", "easy", ["python"], "What is the difference between a shallow copy and a deep copy in Python and when does it matter?", "A shallow copy creates a new container that still references the same inner objects, while a deep copy also copies the inner objects. It matters with nested lists or dictionaries, where changing an inner item through a shallow copy changes the original too.", ["Shared inner objects", "copy vs deepcopy", "Nested data"], ["How would you copy a list of dictionaries safely?"]),
    q("python", "medium", ["django"], "How do Django's ORM, migrations and class-based views fit together in a simple CRUD application?", "Models describe tables, migrations apply model changes to the database, and class-based views such as ListView and CreateView provide ready-made list and form behaviour using those models and templates or serializers. URLs map paths to views.", ["Models and migrations", "Generic class-based views", "URL routing"], ["How would you add permissions to a view?"]),
    q("python", "medium", ["fastapi"], "What advantages does FastAPI give for building APIs and how do you structure a growing project?", "FastAPI gives type-based validation, automatic documentation and async support. Structure a growing project with routers per feature, schemas, services and a database layer, with dependencies for authentication and configuration.", ["Typed validation and docs", "Routers per feature", "Dependencies for shared logic"], ["How do you test a FastAPI route?"]),
    q("python", "hard", ["concurrency"], "How would you speed up a Python program that downloads 5,000 web pages?", "The work is I/O-bound, so use asyncio with an async HTTP client or a thread pool with limited concurrency, respect rate limits, add timeouts and retries and process results as they arrive. Multiprocessing is not needed for waiting.", ["I/O-bound concurrency", "Limit concurrency and add timeouts", "Retries"], ["What would change for CPU-heavy parsing?"]),
    q("dsa", "easy", ["strings"], "How would you check whether a string is a palindrome ignoring case and punctuation?", "Clean the string by keeping only letters and digits in lowercase and compare it with its reverse, or use two pointers moving inward, which is O(n) time. Treat an empty cleaned string as a defined case.", ["Normalise first", "Compare with reverse or two pointers", "O(n)"], ["Which approach uses less memory?"]),
    q("dsa", "medium", ["stack"], "How would you check whether a string of brackets such as ({[]}) is balanced?", "Scan the string, push opening brackets on a stack and when you see a closing bracket check that the top of the stack matches, popping it, and at the end the stack must be empty. It is O(n).", ["Stack of opening brackets", "Match on closing", "Empty at the end"], ["What breaks if you only count brackets?"]),
    q("dsa", "medium", ["hashing"], "How would you find the most frequent word in a large text and what is the complexity?", "Count words in a dictionary or Counter while scanning once and then take the maximum count, which is O(n) time with memory proportional to the number of distinct words. Normalise case and punctuation first.", ["Dictionary counts", "One pass", "Normalise first"], ["How would you get the top 10 words?"]),
    q("dsa", "hard", ["recursion"], "How would you generate all subsets of a list and what is the complexity?", "Use recursion or iteration where each element is either included or not, building subsets step by step, which produces 2 to the power n subsets, so time and output size are exponential. Backtracking models this cleanly.", ["Include or exclude each item", "2^n results", "Backtracking"], ["How would you avoid duplicates when the list has repeats?"]),
    q("sql", "easy", ["joins"], "What are the different types of SQL joins and when would you use a LEFT JOIN?", "INNER JOIN returns matching rows, LEFT JOIN returns all rows from the left table and matches from the right, RIGHT JOIN the reverse and FULL JOIN all rows from both. Use LEFT JOIN when you want to keep rows even when there is no match, such as users without orders.", ["Four join types", "LEFT keeps unmatched left rows", "Example with orders"], ["How do you find rows with no match?"]),
    q("sql", "medium", ["aggregation"], "Write the idea of a query that returns customers who placed more than 3 orders and spent over 10,000 in total.", "Join customers to orders, group by customer, compute COUNT of orders and SUM of the amount and use HAVING with both conditions.", ["GROUP BY customer", "COUNT and SUM", "HAVING for both conditions"], ["How would you order by total spent?"]),
    q("web", "medium", ["javascript"], "How do you debounce a search input and why is it needed?", "Debouncing delays calling the search until the user has stopped typing for a short time, using a timer that resets on each keystroke. This avoids sending a request for every key press and reduces load and flicker.", ["Timer that resets", "Fewer requests", "Better responsiveness"], ["What is the difference from throttling?"]),
    q("web", "medium", ["react"], "How would you manage a form with validation and server errors in React?", "Keep field values in state or use a form library, validate on submit and on blur, show messages next to the fields, disable the submit button while sending and display errors returned by the server. Also validate on the server.", ["Controlled fields and validation", "Show field-level errors", "Server validation too"], ["How do you keep the form accessible?"]),
    q("web", "hard", ["security"], "How do you protect a web application against XSS, CSRF and SQL injection?", "Escape output and use a content security policy against XSS, use SameSite cookies and CSRF tokens against CSRF, and parameterised queries or an ORM against SQL injection. Validate input and keep dependencies updated.", ["Escape, CSP", "SameSite and tokens", "Parameterised queries"], ["Which of these can a front end alone stop?"]),
    q("mobile", "medium", ["cross-platform"], "What factors would make you choose a cross-platform framework over native development for a client app?", "Budget, timeline and team skills favour cross-platform because one code base serves both platforms, while heavy graphics, advanced device features and top performance favour native. Consider long-term maintenance.", ["Cost and speed", "Performance and device features", "Maintenance"], ["How do you handle a platform-specific feature?"]),
    q("mobile", "medium", ["api"], "How should a mobile app handle API errors, retries and expired logins?", "Show clear messages, retry transient failures with backoff, avoid retrying unsafe requests blindly, refresh an expired token once and send the user to login when refresh fails. Cache data to work offline when possible.", ["Clear messages", "Backoff for transient failures", "Token refresh"], ["Why is retrying a payment request risky?"]),
    q("cloud", "easy", ["cloud"], "What are virtual machines, containers and serverless functions, and how do they differ?", "A virtual machine includes a whole operating system, a container packages an app with its dependencies and shares the host kernel, and a serverless function runs code on demand without managing servers. They trade control for simplicity.", ["Three compute models", "Control vs convenience", "Cost and startup differences"], ["Which would you choose for a small API?"]),
    q("cloud", "medium", ["deployment"], "How would you deploy a Django or FastAPI application to the cloud with a managed database?", "Containerise the app, run it on a managed service behind a load balancer, use a managed database with backups, keep configuration and secrets in environment variables or a secrets manager and set up logs, health checks and CI/CD.", ["Container and managed hosting", "Managed database and backups", "Secrets, logs, CI/CD"], ["How do you run migrations on deploy?"]),
    q("cloud", "hard", ["cost"], "How would you keep cloud costs under control for a growing product?", "Tag resources and review the bill by service, right-size and shut down idle resources, use autoscaling, set lifecycle rules on storage, cache to reduce load and set budgets and alerts.", ["Visibility by tag", "Right-size and autoscale", "Budgets and alerts"], ["How do you balance cost against reliability?"]),
    q("devops", "medium", ["ci-cd"], "What does a good CI/CD pipeline contain for a web project?", "Linting and tests on every push, a build, security checks for dependencies, deployment to a staging environment with smoke tests, then a controlled release to production with rollback. Pipelines should be fast and repeatable.", ["Lint and test", "Staging and smoke tests", "Controlled release and rollback"], ["How do you keep a pipeline fast?"]),
    q("testing", "medium", ["testing"], "How do you decide what to automate and what to test manually?", "Automate stable, repeated and high-risk checks such as regression and API tests, and keep new features, usability and exploratory testing manual at first. Review the suite so it stays reliable and cheap to maintain.", ["Automate repeated stable checks", "Manual for exploration", "Maintain the suite"], ["What do you do with a flaky automated test?"]),
    q("vt-scenario", "medium", ["debugging"], "Scenario: a client says the site is slow every afternoon. How do you investigate?", "Check monitoring and logs for that time window, look for traffic peaks, scheduled jobs, slow queries or resource limits, reproduce with a load test, fix the cause such as an index or a job schedule, and add alerts.", ["Correlate with the time window", "Traffic, jobs, queries", "Fix and alert"], ["How would you explain it to the client?"], kind="scenario"),
    q("vt-scenario", "hard", ["design"], "Scenario: design an appointment booking system for clinics that prevents double booking and sends reminders.", "Model slots with a unique constraint on clinic, practitioner and time so only one booking succeeds, reserve in a transaction, send reminders from a scheduled job through a queue with idempotent messages and let users reschedule and cancel.", ["Unique slot constraint", "Transactional booking", "Queued idempotent reminders"], ["How do you handle time zones?"], kind="scenario"),
    q("vt-scenario", "easy", ["teamwork"], "Scenario: a new teammate struggles with your code base. How do you help?", "Pair with them on a small task, point them to documentation and tests, explain the structure and decisions, welcome questions and improve the README based on what confused them.", ["Pair on a small task", "Documentation and tests", "Improve the README"], ["How do you give review feedback kindly?"], kind="scenario"),
    q("git", "easy", ["git"], "What do git stash, git cherry-pick and git revert do and when would you use each?", "Stash saves uncommitted changes temporarily, cherry-pick applies one specific commit to another branch and revert creates a new commit that undoes an earlier one without rewriting history. Use revert for shared branches.", ["Temporary save", "Copy one commit", "Safe undo for shared history"], ["How do you recover a deleted branch?"]),
    q("project", "easy", ["projects"], "Describe a project you built with Python, a web framework or mobile tools. What did you build yourself, what failed and how did you fix it?", "A strong answer is specific about the goal, stack and your own part, names a real failure and the fix and says how you tested and deployed it.", ["Own part and stack", "A real failure and fix", "Testing and deployment"], ["What would you improve first?"], kind="scenario", roles=VT),
]


def build():
    return write("vteams", VT, ITEMS)


if __name__ == "__main__":
    build()
